const MEDIA_TYPES = {
  jpg: "image/jpeg",
  png: "image/png",
  webp: "image/webp",
  gif: "image/gif",
  mp4: "video/mp4",
  webm: "video/webm"
};

export async function onRequestGet({ request, env }) {
  try {
    const url = new URL(request.url);
    const key = url.searchParams.get("key");

    // Accept only keys generated by the Sponsored upload endpoint.
    const validKey =
      /^sponsored-[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp|gif|mp4|webm)$/i;

    if (!key || !validKey.test(key)) {
      return new Response("Media not found.", { status: 404 });
    }

    if (!env.SPONSORED_MEDIA) {
      return new Response("Media service unavailable.", {
        status: 500
      });
    }

    const object = await env.SPONSORED_MEDIA.get(key);

    if (!object) {
      return new Response("Media not found.", { status: 404 });
    }

    const extension = key.split(".").pop().toLowerCase();
    const contentType = MEDIA_TYPES[extension];

    return new Response(object.body, {
      status: 200,
      headers: {
        "Content-Type": contentType,
        "Content-Length": String(object.size),
        "Cache-Control": "public, max-age=31536000, immutable",
        "X-Content-Type-Options": "nosniff",
        "Accept-Ranges": "none"
      }
    });

  } catch (error) {
    return new Response("Unable to load media.", {
      status: 500
    });
  }
}
